public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the array has only one element, return a list containing only one list with that element
    if (nums.length == 1) {
        permutations.add(new ArrayList<Integer>(Arrays.asList(nums[0])));
        return permutations;
    }

    // Recursive case: for each element in the array, remove it and generate all possible permutations of the remaining elements
    for (int i = 0; i < nums.length; i++) {
        // Clone the array and remove the current element
        int[] remainingNum = Arrays.copyOfRange(nums, 1, nums.length);

        // Generate all possible permutations of the remaining elements
        List<List<Integer>> remainingPermutations = permute(remainingNum);

        // Add the current element to each permutation in the remainingPermutations list
        for (List<Integer> permutation : remainingPermutations) {
            permutation.add(0, nums[i]);
        }

        // Add the current permutation to the overall list of permutations
        permutations.addAll(remainingPermutations);
    }

    return permutations;
}

