public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

    // Create a matrix to represent the n-teresting space
    int[][] matrix = new int[n][n];

    // Set the starting and ending points
    matrix[start[0]][start[1]] = 1;
    matrix[end[0]][end[1]] = 2;

    // Add the paths to the matrix
    for (int[] path : paths) {
        matrix[path[0]][path[1]] = matrix[path[1]][path[0]] = 1;
    }

    // Check if the matrix is connected
    if (isConnected(matrix)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

