public static String convertDatesToWeekdays(String date) {
    int month = Character.getNumericValue(date.charAt(0));
    int day = Character.getNumericValue(date.charAt(1));
    int year = Character.getNumericValue(date.charAt(2));

    int dayOfMonth = 0;
    int dayOfWeek = 0;

    if (year >= 1901 && year <= 2000) {
        dayOfMonth = (26 * month + 1) / 10 + month * 30 + day;
        dayOfWeek = (dayOfMonth + year + (year / 4)) % 7;
    } else if (year >= 2000) {
        dayOfMonth = month * 30 + day;
        dayOfWeek = (dayOfMonth + year + (year / 4)) % 7;
    }

    switch(dayOfWeek) {
        case 0:
            return "Sunday";
        case 1:
            return "Monday";
        case 2:
            return "Tuesday";
        case 3:
            return "Wednesday";
        case 4:
            return "Thursday";
        case 5:
            return "Friday";
        case 6:
            return "Saturday";
        default:
            throw new IllegalArgumentException("Invalid date: " + date);
    }
}

