public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Queue<Integer> q = new LinkedList<>();
    boolean[] seen = new boolean[n];
    int time = 0;
    q.add(0);
    while (!q.isEmpty()) {
        int node = q.poll();
        if (!seen[node]) {
            seen[node] = true;
            time++;
            if (hasApple[node]) {
                return time;
            }
            for (int edge : edges[node]) {
                if (!seen[edge]) {
                    q.add(edge);
                }
            }
        }
    }
    return 0;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);

    String result = "";

    for (int i = 0; i < chars.length; i++) {
        if (i % 2 == 0) {
            // pick the smallest character from s
            result += chars[i];
        } else {
            // pick the smallest character from s which is greater than the last appended character
            int nextIndex = i + 1;
            while (nextIndex < chars.length && chars[nextIndex] <= chars[i - 1]) {
                nextIndex++;
            }
            result += chars[nextIndex];
        }
    }

    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the average of the entire array
    double total = 0;
    for (int num : nums) {
        total += num;
    }
    double average = total / nums.length;

    // Check if it is possible to split the array into two non-empty arrays with the same average
    for (int i = 1; i < nums.length; i++) {
        double sum1 = 0, sum2 = 0;
        for (int j = 0; j < i; j++) {
            sum1 += nums[j];
        }
        for (int j = i; j < nums.length; j++) {
            sum2 += nums[j];
        }
        if (sum1 / i == average && sum2 / (nums.length - i) == average) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int res = 0;
    for (int i = 0; i < cost.length; i++) {
        int curCost = cost[i];
        if (i == 0) {
            res = curCost;
        } else if (i == 1) {
            res = Math.min(curCost, res);
        } else if (i == cost.length - 1) {
            res = Math.min(curCost, res + cost[i - 1]);
        } else {
            res = Math.min(curCost + cost[i - 2], res + cost[i - 1]);
        }
    }
    return res;
}

