public int findMinFibonacciNumbers(int k) {
  // Base case: When k is 0, the sum is 0 and there are 0 Fibonacci numbers.
  if (k == 0) return 0;

  // Initialize an array to store the Fibonacci numbers.
  int[] fib = new int[k];

  // Initialize the first two Fibonacci numbers.
  fib[0] = 1;
  fib[1] = 1;

  // Loop through the remaining elements and calculate the Fibonacci numbers.
  for (int i = 2; i < k; i++) {
    fib[i] = fib[i - 1] + fib[i - 2];
  }

  // Initialize the minimum number of Fibonacci numbers to add up to k.
  int minNumberOfFibs = 0;

  // Loop through the Fibonacci numbers and check if the sum of each number of
  // consecutive Fibonacci numbers is less than or equal to k.
  for (int i = 0; i < fib.length; i++) {
    int sum = 0;
    for (int j = 0; j <= i; j++) {
      sum += fib[j];
      if (sum > k) break;
      if (sum == k) {
        minNumberOfFibs = i;
      }
    }
  }

  return minNumberOfFibs;
}

