public static List<Integer> findSteppingNumbers(int low, int high) {

    List<Integer> steppingNumbers = new ArrayList<>();

    for (int i = low; i <= high; i++) {
        int num = i;
        int prevDigit = 0;
        int currentDigit = 0;
        int nextDigit = 0;
        boolean foundSteppingNumber = true;

        while (num > 0) {
            prevDigit = currentDigit;
            currentDigit = nextDigit;
            nextDigit = num % 10;
            num /= 10;

            if (currentDigit == prevDigit + 1 || currentDigit == nextDigit - 1) {
                continue;
            } else {
                foundSteppingNumber = false;
                break;
            }
        }

        if (foundSteppingNumber && i == currentDigit) {
            steppingNumbers.add(i);
        }
    }

    return steppingNumbers;
}

