public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] dirs = new int[][]{{0, 1}, {1, 0}, {1, 1}, {1, -1}};
    int longest = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                for (int[] dir : dirs) {
                    int curr = 1;
                    int x = i + dir[0];
                    int y = j + dir[1];
                    while (x >= 0 && x < m && y >= 0 && y < n && mat[x][y] == 1) {
                        curr++;
                        x += dir[0];
                        y += dir[1];
                    }
                    longest = Math.max(longest, curr);
                }
            }
        }
    }
    return longest;
}

