    int x2 = points[1][0]; int y2 = points[1][1];
    int x3 = points[2][0]; int y3 = points[2][1];

    double s = (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2;

    return s * s == (x1 * x1 + y1 * y1) * (x2 * x2 + y2 * y2) + 
                   (x2 * x2 + y2 * y2) * (x3 * x3 + y3 * y3) +
                   (x3 * x3 + y3 * y3) * (x1 * x1 + y1 * y1) -
                   2 * (x1 * x1 + y1 * y1) * (x2 * x2 + y2 * y2) * (x3 * x3 + y3 * y3);
}

